api_doc_specs = [('supervisor', 'show_profile'), ('supervisor', 'show_account_passwords'), ('spotify', 'login'), ('spotify', 'show_playlist_library'), ('spotify', 'show_liked_songs'), ('spotify', 'show_song_reviews'), ('spotify', 'review_song'), ('spotify', 'update_song_review'), ('supervisor', 'complete_task')]
public_api_docs = {}
for app_name, api_name in api_doc_specs:
    public_api_docs[(app_name, api_name)] = apis.api_docs.show_api_doc(app_name=app_name, api_name=api_name)

playlist_song_ids = set()
for playlist in playlist_library:
    playlist_song_ids.update(playlist['song_ids'])
liked_song_ids = {song['song_id'] for song in liked_songs}
target_song_ids = sorted(playlist_song_ids.intersection(liked_song_ids))
print({'target_song_count': len(target_song_ids), 'target_song_ids': target_song_ids})

reviews_by_song = {}
for song_id in target_song_ids:
    song_reviews = []
    review_page_index = 0
    while True:
        review_page = apis.spotify.show_song_reviews(song_id=song_id, user_email=profile['email'], page_index=review_page_index, page_limit=20)
        song_reviews.extend(review_page)
        if len(review_page) < 20:
            break
        review_page_index += 1
    reviews_by_song[song_id] = song_reviews
print([{'song_id': song_id, 'review_count': len(reviews_by_song[song_id]), 'ratings': [review['rating'] for review in reviews_by_song[song_id]]} for song_id in target_song_ids])

mutation_plan = []
for song_id in target_song_ids:
    existing_reviews = reviews_by_song[song_id]
    if not existing_reviews:
        mutation_plan.append({'action': 'create', 'song_id': song_id, 'rating': 5})
    else:
        for review in existing_reviews:
            if review['rating'] != 5:
                mutation_plan.append({'action': 'update', 'song_id': song_id, 'review_id': review['song_review_id'], 'rating': 5})
print(mutation_plan)

mutation_results = []
for mutation in mutation_plan:
    if mutation['action'] == 'create':
        result = apis.spotify.review_song(song_id=mutation['song_id'], rating=mutation['rating'], access_token=spotify_access_token)
    else:
        result = apis.spotify.update_song_review(review_id=mutation['review_id'], rating=mutation['rating'], access_token=spotify_access_token)
    mutation_results.append({'action': mutation['action'], 'song_id': mutation['song_id'], 'result': result})
print({'planned_mutation_count': len(mutation_plan), 'mutation_response_count': len(mutation_results)})

