reviews_to_update = []
song_ids_to_review = []
for song_id in target_song_ids:
    personal_reviews = target_reviews_by_song_id[song_id]
    if not personal_reviews:
        song_ids_to_review.append(song_id)
    else:
        for review in personal_reviews:
            if review["rating"] != 4:
                reviews_to_update.append({"song_id": song_id, "review_id": review["song_review_id"]})
mutation_plan_is_consistent = (
    all(item["song_id"] in target_songs_by_id for item in reviews_to_update)
    and all(any(review["song_review_id"] == item["review_id"] and review["rating"] != 4 for review in target_reviews_by_song_id[item["song_id"]]) for item in reviews_to_update)
    and all(song_id in target_songs_by_id and not target_reviews_by_song_id[song_id] for song_id in song_ids_to_review)
)
if not mutation_plan_is_consistent:
    raise RuntimeError("Derived Spotify review mutations are inconsistent with the observed public records.")
print({"target_song_count": len(target_song_ids), "review_update_count": len(reviews_to_update), "review_create_count": len(song_ids_to_review)})

review_update_results = []
for mutation in reviews_to_update:
    review_update_results.append(apis.spotify.update_song_review(review_id=mutation["review_id"], access_token=spotify_access_token, rating=4))
review_create_results = []
for song_id in song_ids_to_review:
    review_create_results.append(apis.spotify.review_song(song_id=song_id, rating=4, access_token=spotify_access_token))

if not verification_passed:
    raise RuntimeError("The requested Spotify 4-star ratings were not verified.")
completion_result = apis.supervisor.complete_task(status="success")

unique_recommended_song_ids = list(dict.fromkeys(recommendation["song_id"] for recommendation in recommendations))
recommended_song_records_by_id = {}
for song_id in unique_recommended_song_ids:
    song_record = apis.spotify.show_song(song_id=song_id)
    if song_record["song_id"] != song_id:
        raise ValueError("Song lookup returned a mismatched song_id")
    recommended_song_records_by_id[song_id] = song_record
print({"canonical_song_records_loaded": len(recommended_song_records_by_id)})

artist_recommendation_counts = {}
for recommendation in recommendations:
    song_record = recommended_song_records_by_id[recommendation["song_id"]]
    artist_ids_on_song = set()
    for artist in song_record["artists"]:
        artist_id = artist["id"]
        if artist_id in artist_ids_on_song:
            continue
        artist_ids_on_song.add(artist_id)
        artist_recommendation_counts[artist_id] = artist_recommendation_counts.get(artist_id, 0) + 1
