def parse_calendar_date(public_date_value):
    date_text = str(public_date_value).strip()
    if len(date_text) > 10 and date_text[10:11].casefold() == "t":
        date_text = date_text[:10]
    normalized = date_text
    for separator in (",", "/", "-", "."):
        normalized = normalized.replace(separator, " ")
    tokens = [token for token in normalized.split() if token]
    month_numbers = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "may": 5, "jun": 6, "jul": 7, "aug": 8,
        "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }
    def token_number(token):
        digits = "".join(character for character in token if character.isdigit())
        return int(digits) if digits else None
    month_positions = [
        (index, month_numbers[token[:3].casefold()])
        for index, token in enumerate(tokens)
        if token[:3].casefold() in month_numbers
    ]
    if month_positions:
        month_position, month = month_positions[0]
        numbered = [(index, token_number(token)) for index, token in enumerate(tokens)]
        year_candidates = [item for item in numbered if item[1] is not None and item[1] >= 1000]
        if not year_candidates:
            raise ValueError("Date has no four-digit year")
        year_position, year = year_candidates[0]
        day_candidates = [
            item for item in numbered
            if item[1] is not None and 1 <= item[1] <= 31 and item[0] not in (month_position, year_position)
        ]
        if not day_candidates:
            raise ValueError("Date has no day")
        _, day = min(day_candidates, key=lambda item: abs(item[0] - month_position))
    else:
        numeric_tokens = [(token, token_number(token)) for token in tokens if token_number(token) is not None]
        if len(numeric_tokens) < 3:
            raise ValueError("Unsupported public date format")
        first_token, first = numeric_tokens[0]
        second_token, second = numeric_tokens[1]
        third_token, third = numeric_tokens[2]
        if len(first_token) == 4 or first >= 1000:
            year, month, day = first, second, third
        elif len(third_token) == 4 or third >= 1000:
            year = third
            if first > 12 and second <= 12:
                day, month = first, second
            elif second > 12 and first <= 12:
                month, day = first, second
            else:
                raise ValueError("Ambiguous numeric public date")
        else:
            raise ValueError("Date has no four-digit year")
    if not (1 <= month <= 12 and 1 <= day <= 31):
        raise ValueError("Invalid public calendar date")
    return (year, month, day)

