    else:
        current_month, current_day, current_year = [int(piece) for piece in date_pieces]
else:
    date_words = raw_current_date.replace(",", "").split()
    month_position = next(index for index, word in enumerate(date_words) if word.lower() in month_numbers)
    current_month = month_numbers[date_words[month_position].lower()]
