    raise ValueError("Dinner-share note selection is ambiguous")
selected_dinner_note = top_candidates[0]

self_aliases = {
    normalized_identity(supervisor_profile["first_name"]),
    normalized_identity(supervisor_profile["last_name"]),
    normalized_identity(supervisor_profile["first_name"] + supervisor_profile["last_name"]),
    str(supervisor_profile["email"]).lower(),
}

owed_shares = []
unmatched_share_labels = []
seen_owed_emails = set()
for parsed_share in selected_dinner_note["parsed_shares"]:
    label = parsed_share["label"]
    label_normalized = normalized_identity(label)
    if label_normalized in self_aliases or str(label).lower() in self_aliases:
        continue
    exact_matches = []
    for contact in coworker_contacts:
        aliases = {
            normalized_identity(contact["first_name"]),
            normalized_identity(contact["last_name"]),
            normalized_identity(contact["first_name"] + contact["last_name"]),
            str(contact["email"]).lower(),
        }
        if label_normalized in aliases or str(label).lower() in aliases:
            exact_matches.append(contact)
    matches = exact_matches
    if not matches:
        matches = [
            contact for contact in coworker_contacts
            if label_normalized and any(
                alias and (alias in label_normalized or label_normalized in alias)
                for alias in (
                    normalized_identity(contact["first_name"]),
                    normalized_identity(contact["first_name"] + contact["last_name"]),
                )
            )
        ]
    unique_matches = {str(contact["email"]).lower(): contact for contact in matches}
    if len(unique_matches) != 1:
        unmatched_share_labels.append({"label": label, "candidate_emails": sorted(unique_matches)})
        continue
    email_key, contact = next(iter(unique_matches.items()))
    if email_key in seen_owed_emails:
        raise ValueError("A coworker appears more than once in the selected share note")
    seen_owed_emails.add(email_key)
    owed_shares.append({
        "label": label,
        "contact_name": (contact["first_name"] + " " + contact["last_name"]).strip(),
        "user_email": contact["email"],
        "amount_cents": parsed_share["amount_cents"],
        "amount": parsed_share["amount_cents"] / 100,
    })

if unmatched_share_labels:
    raise ValueError("Some share labels did not map uniquely to coworker contacts: " + repr(unmatched_share_labels))
