def first_positive_number(text):
    runs = []
    current = ''
    for ch in str(text):
        if ch.isdigit() or ch in '.,':
            current += ch
        elif current:
            runs.append(current)
            current = ''
    if current:
        runs.append(current)
    for run in runs:
        cleaned = run.replace(',', '')
        if cleaned.count('.') <= 1 and any(ch.isdigit() for ch in cleaned):
            try:
                value = float(cleaned)
            except ValueError:
                continue
            if value > 0:
                return value
    return None
if not coworker_contacts:
    raise RuntimeError('No coworker contacts were found')
if not dinner_note_details:
    raise RuntimeError('No dinner note was found')
first_name_counts = {}
for contact in coworker_contacts:
    first_key = contact['first_name'].strip().casefold()
    first_name_counts[first_key] = first_name_counts.get(first_key, 0) + 1
parsed_note_candidates = []
for note in dinner_note_details:
    parsed_shares = {}
    for contact in coworker_contacts:
        email = contact['email'].strip().casefold()
        full_name = (contact['first_name'] + ' ' + contact['last_name']).strip()
        identifiers = [contact['email'], full_name]
        if first_name_counts.get(contact['first_name'].strip().casefold()) == 1:
            identifiers.append(contact['first_name'])
        amount = None
        for line in note['content'].splitlines() or [note['content']]:
            lower_line = line.casefold()
            for identifier in identifiers:
                identifier_text = identifier.strip()
                position = lower_line.find(identifier_text.casefold())
                if position >= 0:
                    amount = first_positive_number(line[position + len(identifier_text):])
                    if amount is None:
                        amount = first_positive_number(line)
                    if amount is not None:
                        break
            if amount is not None:
                break
        if amount is not None:
            parsed_shares[email] = {'contact': contact, 'amount': amount}
    parsed_note_candidates.append({'note': note, 'shares': parsed_shares})
selected_note_entry = max(parsed_note_candidates, key=lambda entry: (len(entry['shares']), 'dinner' in (entry['note']['title'] + ' ' + entry['note']['content']).casefold(), entry['note']['updated_at']))
