steps.action_code:
target_item_text = "Taking a solo backpacking trip"
item_search_summaries = fetch_all_note_summaries(target_item_text)

candidate_summaries_by_id = {}
for summary in bucket_search_summaries + item_search_summaries:
    candidate_summaries_by_id[summary["note_id"]] = summary

candidate_note_details = []
for note_id in candidate_summaries_by_id:
    candidate_note_details.append(
        apis.simple_note.show_note(
            note_id=note_id,
            access_token=simple_note_access_token,
        )
    )

def checkbox_item_transition(line, item_text):
    body = line.rstrip("\r\n")
    line_ending = line[len(body):]
    if body.count(item_text) != 1:
        return None, line
    item_position = body.find(item_text)
    if body[item_position + len(item_text):].strip() != "":
        return None, line
    prefix = body[:item_position]
    trimmed_prefix = prefix.rstrip()
    spacing = prefix[len(trimmed_prefix):]
    lowered_prefix = trimmed_prefix.lower()
    checked_bracket_markers = ("[x]", "[✓]", "[✔]", "[☑]")
    for marker in checked_bracket_markers:
        if lowered_prefix.endswith(marker):
            replacement_prefix = trimmed_prefix[:-len(marker)] + "[ ]"
            return "checked", replacement_prefix + spacing + body[item_position:] + line_ending
    if trimmed_prefix.endswith("[ ]"):
        return "unchecked", line
    checked_symbols = {"☑": "☐", "☒": "☐", "✅": "⬜"}
    for marker, replacement in checked_symbols.items():
        if trimmed_prefix.endswith(marker):
            replacement_prefix = trimmed_prefix[:-len(marker)] + replacement
            return "checked", replacement_prefix + spacing + body[item_position:] + line_ending
    if trimmed_prefix.endswith(("☐", "⬜", "□")):
        return "unchecked", line
    return None, line

def contains_parseable_target(note_record):
    return any(
        checkbox_item_transition(line, target_item_text)[0] is not None
        for line in note_record["content"].splitlines(keepends=True)
    )

if not any(contains_parseable_target(note) for note in candidate_note_details):
    all_note_summaries = fetch_all_note_summaries("")
    for summary in all_note_summaries:
        if summary["note_id"] not in candidate_summaries_by_id:
            candidate_summaries_by_id[summary["note_id"]] = summary
            candidate_note_details.append(
                apis.simple_note.show_note(
                    note_id=summary["note_id"],
                    access_token=simple_note_access_token,
                )
            )

print([
    {
        "note_id": note["note_id"],
        "title": note["title"],
        "parseable_target_items": sum(
            1
            for line in note["content"].splitlines(keepends=True)
            if checkbox_item_transition(line, target_item_text)[0] is not None
        ),
    }
    for note in candidate_note_details
    if target_item_text in note["content"]
])

eligible_note_records = []
for note in candidate_note_details:
    source_lines = note["content"].splitlines(keepends=True)
    parsed_item_lines = []
    for line_index, line in enumerate(source_lines):
        item_state, replacement_line = checkbox_item_transition(line, target_item_text)
        if item_state is not None:
            parsed_item_lines.append((line_index, item_state, replacement_line))
    if len(parsed_item_lines) == 1:
        normalized_title = "".join(
            character.lower() for character in note["title"] if character.isalnum()
        )
        if normalized_title == "bucketlist":
            title_score = 3
        elif normalized_title.startswith("bucketlist") or normalized_title.endswith("bucketlist"):
            title_score = 2
        elif "bucketlist" in normalized_title:
            title_score = 1
        else:
            title_score = 0
        eligible_note_records.append({
            "note": note,
            "source_lines": source_lines,
            "parsed_item": parsed_item_lines[0],
            "title_score": title_score,
        })

if not eligible_note_records:
    raise RuntimeError("No note contains exactly one parseable target checklist item.")
best_title_score = max(record["title_score"] for record in eligible_note_records)
best_note_records = [
    record for record in eligible_note_records
    if record["title_score"] == best_title_score
]
if len(best_note_records) != 1:
    raise RuntimeError("The target checklist item is ambiguous across candidate notes.")

selected_record = best_note_records[0]
target_note = selected_record["note"]
target_line_index, source_item_state, unchecked_item_line = selected_record["parsed_item"]
updated_lines = list(selected_record["source_lines"])
updated_lines[target_line_index] = unchecked_item_line
updated_note_content = "".join(updated_lines)
print({
    "note_id": target_note["note_id"],
    "title": target_note["title"],
    "current_item_state": source_item_state,
    "content_changes": 0 if updated_note_content == target_note["content"] else 1,
})

verified_note = apis.simple_note.show_note(
    note_id=target_note["note_id"],
    access_token=simple_note_access_token,
)
verified_item_states = []
for line in verified_note["content"].splitlines(keepends=True):
    verified_state, unused_replacement = checkbox_item_transition(line, target_item_text)
    if verified_state is not None:
        verified_item_states.append(verified_state)
if verified_note["content"] != updated_note_content:
    raise RuntimeError("The stored note content does not match the reviewed update.")
if verified_item_states != ["unchecked"]:
    raise RuntimeError("The target item was not uniquely verified as not done.")
print({
    "note_id": verified_note["note_id"],
    "item": target_item_text,
    "verified_state": "not_done",
})

