phone_access_token = phone_login_result["access_token"]

def digit_groups(text):
    groups = []
    current = ""
    for ch in str(text):
        if ch.isdigit():
            current += ch
        elif current:
            groups.append(current)
            current = ""
    if current:
        groups.append(current)
    return groups

month_names = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"]
date_text = str(current_date_time.get("date", ""))
date_lower = date_text.lower()
date_numbers = digit_groups(date_text)
current_year = None
current_month = None
for number in date_numbers:
    value = int(number)
    if len(number) == 4 and 1900 <= value <= 2100:
        current_year = value
        break
for index, month_name in enumerate(month_names, start=1):
    if month_name in date_lower or month_name[:3] in date_lower:
        current_month = index
        break
if current_month is None and len(date_numbers) >= 2 and len(date_numbers[0]) == 4:
    current_month = int(date_numbers[1])
elif current_month is None and len(date_numbers) >= 3 and len(date_numbers[-1]) == 4:
    current_month = int(date_numbers[0])

target_month_terms = []
if current_year is not None and current_month is not None and 1 <= current_month <= 12:
    previous_month = 12 if current_month == 1 else current_month - 1
    previous_year = current_year - 1 if current_month == 1 else current_year
    previous_name = month_names[previous_month - 1]
    target_month_terms = [
        previous_name,
        previous_name[:3] + " ",
        f"{previous_year}-{previous_month:02d}",
        f"{previous_year}/{previous_month:02d}",
        f"{previous_year}_{previous_month:02d}",
        f"{previous_month:02d}-{previous_year}",
        f"{previous_month:02d}/{previous_year}",
        f"{previous_month:02d}_{previous_year}",
        f"{previous_year}{previous_month:02d}",
    ]

def numeric_tokens(text):
    source = str(text)
    tokens = []
    index = 0
    while index < len(source):
        if not source[index].isdigit():
            index += 1
            continue
        end = index
        while end < len(source) and (source[end].isdigit() or source[end] in ",."):
            end += 1
        raw = source[index:end].rstrip(".,")
        cleaned = raw.replace(",", "")
        if cleaned and cleaned.count(".") <= 1:
            try:
                value = float(cleaned)
            except ValueError:
                value = None
            if value is not None:
                decimal_places = len(cleaned.split(".", 1)[1]) if "." in cleaned else 0
                before = source[max(0, index - 6):index].lower()
                after = source[end:min(len(source), end + 8)].lower()
                has_currency = "$" in before or "usd" in before or "usd" in after or "dollar" in after
                tokens.append({"value": value, "start": index, "raw": raw, "decimal_places": decimal_places, "has_currency": has_currency})
        index = max(end, index + 1)
    return tokens

def best_labeled_amount(content):
    source = str(content)
    lower = source.lower()
    labels = ["amount paid", "total paid", "payment amount", "grand total", "total amount", "bill total", "total due", "amount due", "total", "amount", "paid", "current charges"]
    scored = []
    for label_index, label in enumerate(labels):
        cursor = 0
        while True:
            found = lower.find(label, cursor)
            if found < 0:
                break
            before_char = lower[found - 1] if found > 0 else " "
            after_position = found + len(label)
            after_char = lower[after_position] if after_position < len(lower) else " "
            if (before_char.isalnum() or after_char.isalnum()) and label in ("total", "amount", "paid"):
                cursor = found + len(label)
                continue
            window = source[after_position:after_position + 180]
            for token in numeric_tokens(window):
                value = token["value"]
                if value <= 0:
                    continue
                score = 2400 - label_index * 120 - min(token["start"], 160)
                if token["has_currency"]:
                    score += 180
                if token["decimal_places"] == 2:
                    score += 80
                if 1900 <= value <= 2100 and not token["has_currency"]:
                    score -= 900
                if value > 1000000 and not token["has_currency"]:
                    score -= 900
                scored.append((score, value, label, token["raw"]))
            cursor = found + len(label)
    if not scored:
        for token in numeric_tokens(source):
            value = token["value"]
            if value <= 0:
                continue
            nearby = lower[max(0, token["start"] - 50):token["start"] + 50]
            keyword_score = sum(90 for keyword in ("total", "amount", "paid", "charge", "bill") if keyword in nearby)
            score = keyword_score + (180 if token["has_currency"] else 0) + (70 if token["decimal_places"] == 2 else 0)
            if 1900 <= value <= 2100 and not token["has_currency"]:
                score -= 900
            if token["has_currency"] or token["decimal_places"] == 2 or keyword_score:
                scored.append((score, value, "monetary context", token["raw"]))
    if not scored:
        return None
    return max(scored, key=lambda item: item[0])

