def token_to_cents(token):
    cleaned = token.replace(",", "")
    sign = -1 if cleaned.startswith("-") else 1
    cleaned = cleaned.lstrip("+-")
    if "." in cleaned:
        whole, fraction = cleaned.split(".", 1)
